/* gen.h - what the recompiled blocks (gen_all.c, generated by tools/ughrec.py) need.
 *
 * UGH.EXE has several code segments (Borland C++'s far code model).  A block is keyed by its
 * run-time CS (image segment + LOAD_SEG) and IP.  The blocks are made from the program as the PKLITE
 * decompressor leaves it at its entry point; they are switched on there, once the code bytes they
 * were made from have been checked (another version of the program runs in the interpreter). */
#ifndef UGH_GEN_H
#define UGH_GEN_H
#include "../core/cpu.h"
#include "../hal/hal.h"

#define REL(x) ((uint16_t)((x) + LOAD_SEG))

typedef int (*GenFn)(Cpu *c);      /* 1: ran (c->s[CS]:c->ip is the next block), 0: declined */
typedef struct GenBlock {
    uint16_t cs, ip;
    GenFn fn;
} GenBlock;

/* a stretch of the code the blocks were made from, with its FNV-1a hash */
typedef struct GenRange {
    uint32_t lin, len;
    uint64_t hash;
} GenRange;

extern const GenBlock g_gen_blocks[];
extern const unsigned g_gen_block_count;
extern const GenRange g_gen_ranges[];
extern const unsigned g_gen_range_count;
extern const uint16_t g_gen_entry_cs, g_gen_entry_ip;   /* the program's entry (run-time CS) */

void gen_install(int on);           /* the recompiled code runs in place of the interpreter */
int gen_armed(void);                /* 1 once the code was checked at the entry point */
extern uint64_t g_gen_blocks_run;

/* watched addresses: fn runs whenever execution arrives at CS:IP (recompiled or interpreted), before
 * the code there; only once the program has reached its entry point (unpacked) */
typedef void (*GenWatchFn)(Cpu *c);
int gen_watch(uint16_t cs, uint16_t ip, GenWatchFn fn);

#endif
